      }
    },
    {
      "@id": "entity:source-meet_peri.step.1.desc",
      "@type": "prov:Entity",
      "prov:value": "Peri sets the scene and asks your child what they notice. No right answer yet — just looking."
    },
    {
      "@id": "entity:target-meet_peri.step.1.desc-v1",
      "@type": "prov:Entity",
      "prov:value": "「 Peri はシーンをセットし、子供に気づいたことを尋ねます。正解はありません — まだ見ているだけです。」",
      "generated_by": {
        "@id": "activity:translation-meet_peri.step.1.desc-2026-07-09T00:18:57.091763+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.step.1.desc"
      }
    },
    {
      "@id": "activity:translation-meet_peri.step.2.desc-2026-07-09T00:18:57.091763+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T00:18:57.091763+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.step.2.desc",
      "@type": "prov:Entity",
      "prov:value": "Your child records what they see, hear, or measure. Peri prompts for specifics if the answer is vague."
    },
    {
      "@id": "entity:target-meet_peri.step.2.desc-v1",
      "@type": "prov:Entity",
      "prov:value": "子供が見たり、聞いたり、測定したりしたことを記録します。Peri が回答が曖昧な場合に詳細を求めます。",
      "generated_by": {
        "@id": "activity:translation-meet_peri.step.2.desc-2026-07-09T00:18:57.091763+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.step.2.desc"
      }
    },
    {
      "@id": "activity:translation-meet_peri.step.3.desc-2026-07-09T00:19:19.649542+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T00:19:19.649542+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.step.3.desc",
      "@type": "prov:Entity",
      "prov:value": "Peri asks comparison and classification questions. What\\'s similar? What\\'s different? What pattern do you see?"
    },
    {
      "@id": "entity:target-meet_peri.step.3.desc-v1",
      "@type": "prov:Entity",
      "prov:value": "「パリは比較と分類の質問をします。似ているものは何ですか？異なるものは何ですか？どんなパターンが見えますか？」",
      "generated_by": {
        "@id": "activity:translation-meet_peri.step.3.desc-2026-07-09T00:19:19.649542+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.step.3.desc"
      }
    },
    {
      "@id": "activity:translation-meet_peri.step.4.desc-2026-07-09T00:19:19.649542+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T00:19:19.649542+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.step.4.desc",
      "@type": "prov:Entity",
      "prov:value": "Your child proposes a cause or mechanism. Peri tests it with evidence questions, not hints."
    },
    {
      "@id": "entity:target-meet_peri.step.4.desc-v1",
      "@type": "prov:Entity",
      "prov:value": "子供が原因やメカニズムを提案します。ペリは、証拠の質問で、ヒントではなくそれをテストします。",
      "generated_by": {
        "@id": "activity:translation-meet_peri.step.4.desc-2026-07-09T00:19:19.649542+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.step.4.desc"
      }
    },
    {
      "@id": "activity:translation-meet_peri.step.5.desc-2026-07-09T00:19:19.649542+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T00:19:19.649542+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.step.5.desc",
      "@type": "prov:Entity",
      "prov:value": "Peri asks what this means for a new situation. Knowledge becomes portable."
    },
    {
      "@id": "entity:target-meet_peri.step.5.desc-v1",
      "@type": "prov:Entity",
      "prov:value": "「新しい状況で、ペリは何を意味するか尋ねます。知識が移植可能になります。」",
      "generated_by": {
        "@id": "activity:translation-meet_peri.step.5.desc-2026-07-09T00:19:19.649542+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.step.5.desc"
      }
    },
    {
      "@id": "activity:translation-meet_peri.exchange.1.text-2026-07-09T00:19:19.649542+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T00:19:19.649542+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.exchange.1.text",
      "@type": "prov:Entity",
      "prov:value": "You\\'re at the creek bank. Before we measure anything — what\\'s the first thing you notice about the water right here versus ten feet upstream?"
    },
    {
      "@id": "entity:target-meet_peri.exchange.1.text-v1",
      "@type": "prov:Entity",
      "prov:value": "水辺にいます。測定する前に、この地点の水と10フィート上流の水で最初に気づいたことは何ですか？",
      "generated_by": {
        "@id": "activity:translation-meet_peri.exchange.1.text-2026-07-09T00:19:19.649542+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.exchange.1.text"
      }
    },
    {
      "@id": "activity:translation-meet_peri.exchange.2.text-2026-07-09T00:19:19.649542+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T00:19:19.649542+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.exchange.2.text",
      "@type": "prov:Entity",
      "prov:value": "It\\'s slower here and there\\'s more mud on the bottom."
    },
    {
      "@id": "entity:target-meet_peri.exchange.2.text-v1",
      "@type": "prov:Entity",
      "prov:value": "「ここでは遅いし、底に泥が多い。」",
      "generated_by": {
        "@id": "activity:translation-meet_peri.exchange.2.text-2026-07-09T00:19:19.649542+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.exchange.2.text"
      }
    },
    {
      "@id": "activity:translation-meet_peri.exchange.3.text-2026-07-09T00:19:41.843020+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T00:19:41.843020+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.exchange.3.text",
      "@type": "prov:Entity",
      "prov:value": "Good observation. Why do you think the mud settled here and not upstream where the water is faster?"
    },
    {
      "@id": "entity:target-meet_peri.exchange.3.text-v1",
      "@type": "prov:Entity",
      "prov:value": "「その指摘は正しい。なぜ泥がこの地点で沈殿し、上流の水が速いところでは沈まずにいると思うかね？」",
      "generated_by": {
        "@id": "activity:translation-meet_peri.exchange.3.text-2026-07-09T00:19:41.843020+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.exchange.3.text"
      }
    },
    {
      "@id": "activity:translation-meet_peri.exchange.4.text-2026-07-09T00:19:41.843020+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T00:19:41.843020+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.exchange.4.text",
      "@type": "prov:Entity",
      "prov:value": "Maybe slower water can\\'t carry as much stuff?"
    },
    {
      "@id": "entity:target-meet_peri.exchange.4.text-v1",
      "@type": "prov:Entity",
      "prov:value": "「水が遅いと荷物を運べないかもしれませんね」",
      "generated_by": {
        "@id": "activity:translation-meet_peri.exchange.4.text-2026-07-09T00:19:41.843020+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.exchange.4.text"
      }
    },
    {
      "@id": "activity:translation-meet_peri.exchange.5.text-2026-07-09T00:19:41.843020+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T00:19:41.843020+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__General_Balanced_Content_|_Temp__0.3"
      }
    },
    {
      "@id": "entity:source-meet_peri.exchange.5.text",
      "@type": "prov:Entity",
      "prov:value": "That\\'s the right direction. What could you measure or photograph here to support that idea?"
    },
    {
      "@id": "entity:target-meet_peri.exchange.5.text-v1",
      "@type": "prov:Entity",
      "prov:value": "「その方向性は正しい。ここに何を測定したり写真を撮れば、それを支持できるか考えてみてください。」",
      "generated_by": {
        "@id": "activity:translation-meet_peri.exchange.5.text-2026-07-09T00:19:41.843020+00:00"
      },
      "used_source": {
        "@id": "entity:source-meet_peri.exchange.5.text"
      }
    },
    {
