    {
      "@id": "entity:source-privacy.summary_desc",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware complies with COPPA, GDPR, FERPA, CCPA, PIPEDA, LGPD, and PDPA. Student data is never sold, never used for advertising, and never shared without consent."
