      "@id": "activity:translation-components_landingpage.peripateticware_began_as_a_white_paper_w-2026-07-09T01:06:27.615336+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T01:06:27.615336+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-components_landingpage.peripateticware_began_as_a_white_paper_w",
      "@type": "prov:Entity",
      "prov:value": "Peripateticware began as a white paper written inside McGraw-Hill Education. It argued that GPS-enabled mobile devices would transform learning — that students walking through real places, guided by structured inquiry, could learn in a way textbooks never allowed."
    },
    {
      "@id": "entity:target-components_landingpage.peripateticware_began_as_a_white_paper_w-v1",
      "@type": "prov:Entity",
      "prov:value": "「パリペタティックウェアは、マクグロヒル・エデュケーション内で執筆された白書として始まりました。それは、GPSを搭載したモバイルデバイスが学習を変えるだろうと主張し、実地の場所を歩きながら構造化された調査に従って学ぶことで、テキストブックでは決してできないように学べることを提唱しました。」",
      "generated_by": {
        "@id": "activity:translation-components_landingpage.peripateticware_began_as_a_white_paper_w-2026-07-09T01:06:27.615336+00:00"
      },
      "used_source": {
        "@id": "entity:source-components_landingpage.peripateticware_began_as_a_white_paper_w"
      }
    },
