    {
      "@id": "activity:translation-curriculumImportPage.description-2026-07-09T01:14:57.104268+00:00",
      "@type": "prov:Activity",
      "prov:startTime": "2026-07-09T01:14:57.104268+00:00",
      "actor": {
        "@id": "agent:OLLAMA-mistral-nemo_12b_Profile__Technical/Legal_Documentation_|_Temp__0.1"
      }
    },
    {
      "@id": "entity:source-curriculumImportPage.description",
      "@type": "prov:Entity",
      "prov:value": "Upload a PDF or CSV of official state academic standards (TEKS, NGSS, Common Core, etc.). Ollama extracts each standard for review. Once saved as a global set, all teachers and homeschool parents can map their activities against these standards. Re-uploading the same file skips processing (checksum cache)."
    },
    {
      "@id": "entity:target-curriculumImportPage.description-v1",
      "@type": "prov:Entity",
      "prov:value": "「官公式の州学術標準（TEKS、NGSS、共通核心など）をPDFまたはCSV形式でアップロードしてください。Ollamaは各標準を抽出し、保存後全ての教師とホームスクールの両親がこれらの標準に対して活動をマッピングすることができます。同じファイルを再アップロードしても処理はスキップされ（チェックサムキャッシュ）、中断されません。」",
      "generated_by": {
        "@id": "activity:translation-curriculumImportPage.description-2026-07-09T01:14:57.104268+00:00"
      },
      "used_source": {
        "@id": "entity:source-curriculumImportPage.description"
      }
    },
